var n=`0390-bouneschlupp`;var i=`world-0390`;var s=`LU`;var a=`western-europe`;var o=4;var r=45;var l={en:`Bouneschlupp`,ua:`Буншлупп`};var u={en:`A traditional Luxembourg dish made with green beans, potato, yellow onion, bacon. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Люксембург. Основні інгредієнти: стручкова квасоля, картопля, жовта цибуля, бекон. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var d=[{en:`Cook the listed ingredients in simmering water for about 34 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 34 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:34,i:[[`green-beans`,460,`g`],[`potato`,420,`g`],[`water`,1100,`ml`],[`yellow-onion`,150,`g`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 8 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 8 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:8,i:[[`bacon`,170,`g`],[`unsalted-butter`,40,`g`],[`all-purpose-flour`,35,`g`]]},{en:`Stir in these seasonings and additions. Taste, adjust the balance and let the dish stand briefly before serving.`,ua:`Додайте приправи та завершальні складники. Спробуйте, збалансуйте смак і дайте страві трохи настоятися перед подаванням.`,t:[`seasoning`,`finishing-with-herbs`],m:3,i:[[`white-wine-vinegar`,25,`ml`],[`parsley`,22,`g`],[`table-salt`,null,`to_taste`]]}];var g={slug:n,id:i,country:`LU`,region:a,servings:4,minutes:45,title:l,text:u,steps:d};export{s as country,g as default,i as id,r as minutes,a as region,o as servings,n as slug,d as steps,u as text,l as title};